export const tagWriteJobsSchema=`
 CREATE TABLE tag_write_job(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES playable_item(id) ON DELETE RESTRICT,file_id TEXT NOT NULL REFERENCES media_file(id) ON DELETE RESTRICT,
  title TEXT NOT NULL,plan_json TEXT NOT NULL CHECK(json_valid(plan_json) AND length(CAST(plan_json AS BLOB))<=262144),snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json) AND length(CAST(snapshot_json AS BLOB))<=262144),
  state TEXT NOT NULL CHECK(state IN('prepared','running','cancelled','failed','recovery_required','completed')),revision INTEGER NOT NULL CHECK(revision>=0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,reason TEXT NOT NULL);
 CREATE INDEX tag_write_job_page ON tag_write_job(created_at DESC,id DESC);
 CREATE UNIQUE INDEX tag_write_one_active_file ON tag_write_job(file_id) WHERE state IN('running','recovery_required');
 CREATE TRIGGER tag_write_plan_immutable BEFORE UPDATE OF id,item_id,file_id,title,plan_json,snapshot_json,created_at ON tag_write_job BEGIN SELECT RAISE(ABORT,'标签写回计划不可修改'); END;
 CREATE TRIGGER tag_write_job_no_delete BEFORE DELETE ON tag_write_job BEGIN SELECT RAISE(ABORT,'标签写回任务需保留恢复证据'); END;
 CREATE TABLE tag_write_command(command_id TEXT PRIMARY KEY,request_json TEXT NOT NULL CHECK(json_valid(request_json) AND length(CAST(request_json AS BLOB))<=4096),result_json TEXT NOT NULL CHECK(json_valid(result_json) AND length(CAST(result_json AS BLOB))<=262144),created_at TEXT NOT NULL);
 CREATE TRIGGER tag_write_command_immutable BEFORE UPDATE ON tag_write_command BEGIN SELECT RAISE(ABORT,'标签任务回执不可修改'); END;
 CREATE TRIGGER tag_write_command_no_delete BEFORE DELETE ON tag_write_command BEGIN SELECT RAISE(ABORT,'标签任务回执不可删除'); END;
 CREATE TABLE tag_write_file_state(file_id TEXT PRIMARY KEY REFERENCES media_file(id) ON DELETE RESTRICT,source_stamp TEXT NOT NULL,content_revision INTEGER NOT NULL CHECK(content_revision>=0),lease_revision INTEGER NOT NULL CHECK(lease_revision>=0),
  lease_job_id TEXT REFERENCES tag_write_job(id) ON DELETE RESTRICT,lease_id TEXT,lease_state TEXT NOT NULL CHECK(lease_state IN('none','held','recovery')),
  CHECK((lease_state='none' AND lease_job_id IS NULL AND lease_id IS NULL) OR (lease_state IN('held','recovery') AND lease_job_id IS NOT NULL AND lease_id IS NOT NULL)));
 CREATE TRIGGER tag_write_lease_file_insert BEFORE INSERT ON tag_write_file_state WHEN NEW.lease_job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tag_write_job WHERE id=NEW.lease_job_id AND file_id=NEW.file_id) BEGIN SELECT RAISE(ABORT,'标签租约任务不属于当前文件'); END;
 CREATE TRIGGER tag_write_lease_file_update BEFORE UPDATE ON tag_write_file_state WHEN NEW.lease_job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM tag_write_job WHERE id=NEW.lease_job_id AND file_id=NEW.file_id) BEGIN SELECT RAISE(ABORT,'标签租约任务不属于当前文件'); END;
 CREATE TRIGGER tag_write_revision_monotonic BEFORE UPDATE ON tag_write_file_state WHEN NEW.content_revision<OLD.content_revision OR NEW.lease_revision<OLD.lease_revision BEGIN SELECT RAISE(ABORT,'标签文件修订不可倒退'); END;
`;
export interface TagWriteFrozenSnapshot {draft:TagWriteDraft;fingerprint:string;rootPath:string;realRootPath:string;rootAnchor:WatchAnchor;fullPath:string;relativePath:string;before:MediaStat;fileObservation:string;rights:Array<{field:string;origin:string;fingerprint:string}>}
type Row={id:string;item_id:string;file_id:string;title:string;plan_json:string;snapshot_json:string;state:TagWriteJob['state'];revision:number;created_at:string;updated_at:string;reason:string};
type FileState={source_stamp:string;content_revision:number;lease_revision:number;lease_state:'none'|'held'|'recovery';lease_job_id:string|null;lease_id:string|null};
export interface TagStageDescriptor {worker:TagWorkerStart;commands:{validated:string;backup_ready:string;temp_written:string}}
type Execution={id:string;job_id:string;descriptor_json:string;state:NonNullable<TagWriteJob['staging']>['state'];journal_revision:number;journal_sha256:string|null;progress_json:string|null;result_json:string|null};
const digest=(s:string)=>createHash('sha256').update(s).digest('hex');
const canonical=(v:unknown):string=>JSON.stringify(v,(_k,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.keys(x).sort().map(k=>[k,x[k]])):x);
