 private reprobeRow(id:string):ReprobeRow {if(!tagWriteUuid(id))throw new Error('重新解析身份无效');const row=this.db.prepare('SELECT * FROM tag_commit_reprobe WHERE id=?').get(id) as ReprobeRow|undefined;if(!row)throw new Error('重新解析任务不存在');return row;}
