  const row=this.db.prepare('SELECT id,file_id,mode,state,progress_json,reason,updated_at FROM tag_commit_reprobe WHERE job_id=? ORDER BY created_at DESC,id DESC LIMIT 1').get(jobId) as ReprobeRow|undefined;if(!row)return;
