 private restoreView(jobId:string):TagRestoreView|undefined {const row=this.db.prepare('SELECT id,mode,state,journal_revision,progress_json,exit_confirmed,reason FROM tag_restore_operation WHERE job_id=?').get(jobId) as RestoreRow|undefined;if(!row)return;const progress=row.progress_json?JSON.parse(row.progress_json) as {role:string;bytes:string;total:string}:null;return {id:row.id,mode:row.mode,state:row.state,phase:progress?.role??['planned','locked','prepared','intent','displaced','restored','verified'][row.journal_revision]??row.state,bytes:progress?.bytes??'0',total:progress?.total??'0',exitConfirmed:row.exit_confirmed===1,reason:row.reason};}
