 recoveryActionBinding(id:string):{row:RecoveryActionRow;descriptor:TagStageDescriptor;report:TagRecoveryReport;request:TagRecoveryActionRequest} {const row=this.recoveryActionRow(id);if(row.state!=='running')throw new Error('恢复处理已终结');const request=readTagRecoveryAction(JSON.parse(row.request_json)),selected=this.selectedRecovery(request);if(row.job_id!==request.jobId||row.inspection_id!==request.inspectionId||row.execution_id!==selected.descriptor.worker.executionId||row.lease_revision!==selected.descriptor.worker.leaseRevision)throw new Error('恢复处理身份不符');return {row,...selected,request};}
